INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('7bc84645-2abf-42b2-9006-ca8b800ac63f', 'property_casualty', NULL, 'What is material misrepresentation?', '¿Qué es la tergiversación material?', '["A false statement that would have affected the insurer''s decision to provide coverage", "A minor error", "A typo on the application", "A late payment"]', '["Una declaración falsa que habría afectado la decisión del asegurador de proporcionar cobertura", "Un error menor", "Un error tipográfico en la solicitud", "Un pago atrasado"]', 0, 'Material misrepresentation is a false statement significant enough to have influenced the underwriting decision.', 'La tergiversación material es una declaración falsa lo suficientemente significativa para haber influido en la decisión de suscripción.', true, '2026-01-14 22:46:59.817641', '2026-01-14 22:46:59.817641') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('7be007d3-049e-4413-bb94-642747c00299', 'property_casualty', NULL, 'What is blanket coverage?', '¿Qué es la cobertura general?', '["Single amount of coverage that applies to multiple properties or items", "Coverage for a single item", "Liability coverage", "Auto coverage"]', '["Una cantidad única de cobertura que aplica a múltiples propiedades o artículos", "Cobertura para un solo artículo", "Cobertura de responsabilidad", "Cobertura de auto"]', 0, 'Blanket coverage provides a single limit that covers multiple items or locations under one amount.', 'La cobertura general proporciona un solo límite que cubre múltiples artículos o ubicaciones bajo una cantidad.', true, '2026-01-14 22:46:59.656958', '2026-01-14 22:46:59.656958') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('7cfac447-6d0b-4822-a54a-966bfb5e062f', 'property_casualty', NULL, 'What factors affect auto insurance premiums?', '¿Qué factores afectan las primas de seguro de auto?', '["Driving record, age, vehicle type, location, coverage, and credit score", "Only age", "Only vehicle type", "Only driving record"]', '["Historial de manejo, edad, tipo de vehículo, ubicación, cobertura y puntaje de crédito", "Solo edad", "Solo tipo de vehículo", "Solo historial de manejo"]', 0, 'Auto premiums are affected by driving record, age, vehicle, location, coverage amounts, and credit history.', 'Las primas de auto se ven afectadas por historial de manejo, edad, vehículo, ubicación, montos de cobertura e historial de crédito.', true, '2026-01-14 22:49:00.53381', '2026-01-14 22:49:00.53381') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('819053c1-146c-4584-9d9a-bf3c4faab2ee', 'property_casualty', NULL, 'What is warranty in insurance?', '¿Qué es una garantía en seguros?', '["A statement by the insured that must be strictly true for coverage to apply", "A promise by the insurer", "A coverage limit", "A premium discount"]', '["Una declaración del asegurado que debe ser estrictamente verdadera para que aplique la cobertura", "Una promesa del asegurador", "Un límite de cobertura", "Un descuento de prima"]', 0, 'A warranty is a statement made by the insured that must be strictly true; breach may void the policy.', 'Una garantía es una declaración hecha por el asegurado que debe ser estrictamente verdadera; el incumplimiento puede anular la póliza.', true, '2026-01-14 22:46:59.804253', '2026-01-14 22:46:59.804253') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('81c67f78-6b2c-4962-837e-35c38128adff', 'property_casualty', NULL, 'What is the standard workers compensation policy form?', '¿Cuál es el formulario de póliza estándar de compensación de trabajadores?', '["Part A (Workers Comp) and Part B (Employers Liability)", "Only Part A", "Only Part B", "There is no standard form"]', '["Parte A (Compensación de Trabajadores) y Parte B (Responsabilidad del Empleador)", "Solo Parte A", "Solo Parte B", "No hay formulario estándar"]', 0, 'The standard workers compensation policy includes Part A for statutory benefits and Part B for employers liability.', 'La póliza estándar de compensación de trabajadores incluye Parte A para beneficios estatutarios y Parte B para responsabilidad del empleador.', true, '2026-01-14 22:49:00.518499', '2026-01-14 22:49:00.518499') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('821048f3-a078-4dc7-8a80-205e5659e1f9', 'property_casualty', NULL, 'What is reservation of rights?', '¿Qué es la reserva de derechos?', '["A letter from the insurer stating they may deny coverage while investigating", "Approval of a claim", "A policy endorsement", "A premium increase"]', '["Una carta del asegurador indicando que pueden negar cobertura mientras investigan", "Aprobación de un reclamo", "Un endoso de póliza", "Un aumento de prima"]', 0, 'A reservation of rights letter notifies the insured that the insurer may deny coverage while they investigate a claim.', 'Una carta de reserva de derechos notifica al asegurado que el asegurador puede negar cobertura mientras investigan un reclamo.', true, '2026-01-14 22:43:34.620102', '2026-01-14 22:43:34.620102') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('84aace06-33a8-4353-b31f-b577ef33fc3b', 'property_casualty', NULL, 'What is a Commercial Package Policy (CPP)?', '¿Qué es una Póliza de Paquete Comercial (CPP)?', '["A customizable policy combining property and liability coverage for businesses", "A personal auto policy", "A homeowners policy", "A health insurance policy"]', '["Una póliza personalizable que combina cobertura de propiedad y responsabilidad para negocios", "Una póliza de auto personal", "Una póliza de propietarios", "Una póliza de seguro de salud"]', 0, 'A CPP combines various business coverages like property, liability, and crime into one customizable policy.', 'Una CPP combina varias coberturas de negocios como propiedad, responsabilidad y crimen en una póliza personalizable.', true, '2026-01-14 22:43:34.534058', '2026-01-14 22:43:34.534058') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('84c4347f-7cf8-40dd-987f-534a667af017', 'property_casualty', NULL, 'What is the minimum age to obtain a Texas insurance license?', '¿Cuál es la edad mínima para obtener una licencia de seguros de Texas?', '["18 years old", "21 years old", "16 years old", "25 years old"]', '["18 años", "21 años", "16 años", "25 años"]', 0, 'Applicants must be at least 18 years old to obtain a Texas insurance license.', 'Los solicitantes deben tener al menos 18 años para obtener una licencia de seguros de Texas.', true, '2026-01-14 22:43:34.396488', '2026-01-14 22:43:34.396488') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('86db343f-90f3-4fcf-ba26-535a4645ba70', 'property_casualty', NULL, 'What is the watercraft exclusion?', '¿Qué es la exclusión de embarcaciones?', '["Exclusion for liability from larger watercraft in homeowners policies", "Boat coverage", "A coverage addition", "A premium discount"]', '["Exclusión por responsabilidad de embarcaciones más grandes en pólizas de propietarios", "Cobertura de botes", "Una adición de cobertura", "Un descuento de prima"]', 0, 'The watercraft exclusion removes coverage for liability from larger boats and motorized watercraft.', 'La exclusión de embarcaciones elimina cobertura por responsabilidad de botes más grandes y embarcaciones motorizadas.', true, '2026-01-14 22:49:00.493086', '2026-01-14 22:49:00.493086') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('870f3471-67b9-4e25-b4ec-4269dd0edb89', 'property_casualty', NULL, 'What is an insurance fraud?', '¿Qué es el fraude de seguros?', '["Any deliberate deception to obtain an illegitimate gain from insurance", "A legitimate claim", "A policy endorsement", "A coverage limitation"]', '["Cualquier engaño deliberado para obtener una ganancia ilegítima del seguro", "Un reclamo legítimo", "Un endoso de póliza", "Una limitación de cobertura"]', 0, 'Insurance fraud is any intentional act of deception to obtain payment or benefit from an insurance policy.', 'El fraude de seguros es cualquier acto intencional de engaño para obtener pago o beneficio de una póliza de seguro.', true, '2026-01-14 22:43:34.673705', '2026-01-14 22:43:34.673705') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('872c20b6-948e-4130-99c7-3919ae4cb8e5', 'property_casualty', NULL, 'What is recreational vehicle (RV) insurance?', '¿Qué es el seguro de vehículos recreativos (RV)?', '["Coverage combining auto and property features for motorhomes and campers", "Auto insurance only", "Homeowners insurance only", "Liability only"]', '["Cobertura que combina características de auto y propiedad para casas rodantes y campers", "Solo seguro de auto", "Solo seguro de propietarios", "Solo responsabilidad"]', 0, 'RV insurance provides coverage that combines auto-like liability with property coverage for personal belongings inside.', 'El seguro de RV proporciona cobertura que combina responsabilidad tipo auto con cobertura de propiedad para pertenencias personales adentro.', true, '2026-01-14 22:46:59.775129', '2026-01-14 22:46:59.775129') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('8bece97d-a1ff-4cd4-8a54-bbf7dc0413e9', 'property_casualty', NULL, 'What does ''additional insured'' mean?', '¿Qué significa ''asegurado adicional''?', '["A party added to a policy who receives coverage under the named insured''s policy", "The primary policyholder", "The insurance agent", "The claims adjuster"]', '["Una parte agregada a una póliza que recibe cobertura bajo la póliza del asegurado nombrado", "El asegurado principal", "El agente de seguros", "El ajustador de reclamos"]', 0, 'An additional insured is a person or entity added to an insurance policy to receive coverage.', 'Un asegurado adicional es una persona o entidad agregada a una póliza de seguro para recibir cobertura.', true, '2026-01-14 22:49:00.449483', '2026-01-14 22:49:00.449483') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('8e769492-c9c4-4748-bab0-a16cbbf595fe', 'property_casualty', NULL, 'What does ''premium'' mean in insurance?', '¿Qué significa ''prima'' en seguros?', '["The amount paid for insurance coverage", "The deductible amount", "The coverage limit", "The claim amount"]', '["La cantidad pagada por cobertura de seguro", "El monto del deducible", "El límite de cobertura", "El monto del reclamo"]', 0, 'A premium is the amount of money an individual or business pays for an insurance policy, typically on a monthly or annual basis.', 'Una prima es la cantidad de dinero que un individuo o negocio paga por una póliza de seguro, típicamente de forma mensual o anual.', true, '2026-01-14 18:28:35.565207', '2026-01-14 18:28:35.565207') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('8f40a6d3-ed57-4ee5-9151-5ceb4aaba1f0', 'property_casualty', NULL, 'What is Directors and Officers (D&O) liability insurance?', '¿Qué es el seguro de responsabilidad de Directores y Oficiales (D&O)?', '["Coverage protecting company leaders from personal liability for management decisions", "Property coverage", "Auto coverage", "Health coverage"]', '["Cobertura que protege a líderes de la empresa de responsabilidad personal por decisiones de gestión", "Cobertura de propiedad", "Cobertura de auto", "Cobertura de salud"]', 0, 'D&O insurance protects corporate directors and officers from personal liability for decisions made in their official capacity.', 'El seguro D&O protege a directores y oficiales corporativos de responsabilidad personal por decisiones tomadas en su capacidad oficial.', true, '2026-01-14 22:46:59.72927', '2026-01-14 22:46:59.72927') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('901d39f7-c13f-47a4-8f2a-67b029036feb', 'property_casualty', NULL, 'Who is covered under a personal auto policy''s liability coverage?', '¿Quién está cubierto bajo la cobertura de responsabilidad de una póliza de auto personal?', '["The named insured, family members, and permissive users", "Only the named insured", "Only family members", "Only the vehicle owner"]', '["El asegurado nombrado, miembros de la familia y usuarios permitidos", "Solo el asegurado nombrado", "Solo miembros de la familia", "Solo el propietario del vehículo"]', 0, 'Liability coverage typically extends to the named insured, resident family members, and anyone using the vehicle with permission.', 'La cobertura de responsabilidad típicamente se extiende al asegurado nombrado, miembros de la familia residentes y cualquiera que use el vehículo con permiso.', true, '2026-01-14 22:43:34.527581', '2026-01-14 22:43:34.527581') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('903d2a7a-3fff-469e-8e50-c42701f0be78', 'property_casualty', NULL, 'What is fiduciary liability insurance?', '¿Qué es el seguro de responsabilidad fiduciaria?', '["Coverage for claims against those managing employee benefit plans", "Property coverage", "Auto coverage", "Life coverage"]', '["Cobertura para reclamos contra quienes administran planes de beneficios para empleados", "Cobertura de propiedad", "Cobertura de auto", "Cobertura de vida"]', 0, 'Fiduciary liability insurance protects those responsible for managing employee benefit plans from claims of mismanagement.', 'El seguro de responsabilidad fiduciaria protege a quienes son responsables de administrar planes de beneficios para empleados de reclamos de mala gestión.', true, '2026-01-14 22:46:59.735749', '2026-01-14 22:46:59.735749') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('90a068f6-14f1-4784-bfeb-26adb4b5eeaa', 'property_casualty', NULL, 'What is sewer backup coverage?', '¿Qué es la cobertura de respaldo de alcantarillado?', '["Optional coverage for damage from sewers or drains backing up", "Standard coverage", "Liability coverage", "Auto coverage"]', '["Cobertura opcional para daño por alcantarillas o desagües que se respaldan", "Cobertura estándar", "Cobertura de responsabilidad", "Cobertura de auto"]', 0, 'Sewer backup coverage is an optional endorsement covering damage when sewers or drains back up into the home.', 'La cobertura de respaldo de alcantarillado es un endoso opcional que cubre daño cuando las alcantarillas o desagües se respaldan hacia la casa.', true, '2026-01-14 22:46:59.715239', '2026-01-14 22:46:59.715239') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('9154f202-63ac-48cc-bfaa-fd25a8827be9', 'property_casualty', NULL, 'What is motor truck cargo insurance?', '¿Qué es el seguro de carga de camión?', '["Coverage for goods being transported by truck", "Auto liability coverage", "Property coverage", "Workers compensation"]', '["Cobertura para bienes siendo transportados por camión", "Cobertura de responsabilidad de auto", "Cobertura de propiedad", "Compensación de trabajadores"]', 0, 'Motor truck cargo insurance covers goods and merchandise while being transported in a commercial truck.', 'El seguro de carga de camión cubre bienes y mercancía mientras son transportados en un camión comercial.', true, '2026-01-14 22:46:59.759862', '2026-01-14 22:46:59.759862') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('9692677e-b604-4602-baa0-dd250af27553', 'property_casualty', NULL, 'What is bailee coverage?', '¿Qué es la cobertura de depositario?', '["Coverage for property of others in the care, custody, or control of the insured", "Personal property coverage", "Liability coverage", "Auto coverage"]', '["Cobertura para propiedad de otros en el cuidado, custodia o control del asegurado", "Cobertura de propiedad personal", "Cobertura de responsabilidad", "Cobertura de auto"]', 0, 'Bailee coverage protects property belonging to others while it''s in the insured''s possession or control.', 'La cobertura de depositario protege propiedad perteneciente a otros mientras está en posesión o control del asegurado.', true, '2026-01-14 22:46:59.745511', '2026-01-14 22:46:59.745511') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('976899f5-c40f-43c1-86eb-e56c83a7b12b', 'property_casualty', NULL, 'What is boatowners insurance?', '¿Qué es el seguro de propietarios de botes?', '["Coverage for boats including hull damage, liability, and medical payments", "Homeowners coverage", "Auto coverage", "Commercial coverage"]', '["Cobertura para botes incluyendo daño al casco, responsabilidad y pagos médicos", "Cobertura de propietarios", "Cobertura de auto", "Cobertura comercial"]', 0, 'Boatowners insurance covers physical damage to the boat, liability for accidents, and medical payments.', 'El seguro de propietarios de botes cubre daño físico al bote, responsabilidad por accidentes y pagos médicos.', true, '2026-01-14 22:46:59.766634', '2026-01-14 22:46:59.766634') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('98ab0ed0-2569-48ea-89dc-7ba97a43c5ae', 'property_casualty', NULL, 'What is cyber liability insurance?', '¿Qué es el seguro de responsabilidad cibernética?', '["Coverage for losses from data breaches, cyberattacks, and network security failures", "Property coverage", "Auto coverage", "Health coverage"]', '["Cobertura por pérdidas de brechas de datos, ciberataques y fallas de seguridad de red", "Cobertura de propiedad", "Cobertura de auto", "Cobertura de salud"]', 0, 'Cyber liability insurance covers losses from data breaches, cyberattacks, and related incidents.', 'El seguro de responsabilidad cibernética cubre pérdidas de brechas de datos, ciberataques e incidentes relacionados.', true, '2026-01-14 22:46:59.725514', '2026-01-14 22:46:59.725514') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('999198f8-133d-4e87-9002-a566268c962a', 'property_casualty', NULL, 'What is a first-party claim?', '¿Qué es un reclamo de primera parte?', '["A claim made by the insured for their own losses under their policy", "A claim by someone else", "A liability claim", "A third-party claim"]', '["Un reclamo hecho por el asegurado por sus propias pérdidas bajo su póliza", "Un reclamo por alguien más", "Un reclamo de responsabilidad", "Un reclamo de terceros"]', 0, 'A first-party claim is made by the policyholder for their own loss under their own insurance policy.', 'Un reclamo de primera parte es hecho por el asegurado por su propia pérdida bajo su propia póliza de seguro.', true, '2026-01-14 22:43:34.630232', '2026-01-14 22:43:34.630232') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('9a3c32dc-d327-4735-a88b-a0c4676df10a', 'property_casualty', NULL, 'What is a morale hazard?', '¿Qué es un riesgo de moralidad?', '["Carelessness or indifference to loss because insurance exists", "Intentional damage", "A physical hazard", "A coverage limitation"]', '["Descuido o indiferencia a la pérdida porque existe el seguro", "Daño intencional", "Un peligro físico", "Una limitación de cobertura"]', 0, 'Morale hazard is the tendency to be careless or indifferent about preventing losses because insurance will cover them.', 'El riesgo de moralidad es la tendencia a ser descuidado o indiferente sobre prevenir pérdidas porque el seguro las cubrirá.', true, '2026-01-14 22:43:34.577436', '2026-01-14 22:43:34.577436') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('9f2695bb-306f-42cf-ae9b-b0cbb1e7dbce', 'property_casualty', NULL, 'What is the difference between replacement cost and market value?', '¿Cuál es la diferencia entre costo de reemplazo y valor de mercado?', '["Replacement cost is what it costs to rebuild; market value is what the property would sell for", "They are the same", "Market value is always higher", "Replacement cost is always lower"]', '["El costo de reemplazo es lo que cuesta reconstruir; el valor de mercado es por lo que la propiedad se vendería", "Son lo mismo", "El valor de mercado siempre es más alto", "El costo de reemplazo siempre es más bajo"]', 0, 'Replacement cost is the cost to rebuild or replace; market value is what a buyer would pay in the open market.', 'El costo de reemplazo es el costo de reconstruir o reemplazar; el valor de mercado es lo que un comprador pagaría en el mercado abierto.', true, '2026-01-14 22:49:00.521538', '2026-01-14 22:49:00.521538') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('a1a60ba0-a25f-48cb-9cab-61538de6b364', 'property_casualty', NULL, 'What is a hold harmless agreement?', '¿Qué es un acuerdo de exención de responsabilidad?', '["A contract where one party agrees not to hold another liable for certain damages", "An insurance policy", "A coverage endorsement", "A premium payment"]', '["Un contrato donde una parte acuerda no responsabilizar a otra por ciertos daños", "Una póliza de seguro", "Un endoso de cobertura", "Un pago de prima"]', 0, 'A hold harmless agreement is a contract where one party agrees to assume liability for the other party.', 'Un acuerdo de exención de responsabilidad es un contrato donde una parte acuerda asumir responsabilidad por la otra parte.', true, '2026-01-14 22:49:00.455061', '2026-01-14 22:49:00.455061') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('a2020980-5b55-4dd2-a6dd-4f8c5268b1c9', 'property_casualty', NULL, 'What is the law of large numbers?', '¿Qué es la ley de los grandes números?', '["The larger the group of similar exposures, the more predictable the losses", "A counting method", "A policy limit", "A coverage requirement"]', '["Cuanto mayor sea el grupo de exposiciones similares, más predecibles son las pérdidas", "Un método de conteo", "Un límite de póliza", "Un requisito de cobertura"]', 0, 'The law of large numbers states that as the number of similar exposures increases, actual losses become more predictable.', 'La ley de los grandes números establece que a medida que aumenta el número de exposiciones similares, las pérdidas reales se vuelven más predecibles.', true, '2026-01-14 22:43:34.583357', '2026-01-14 22:43:34.583357') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('a247b393-7b1a-4f43-95c1-dc7621e46de4', 'property_casualty', NULL, 'What is waiver in insurance?', '¿Qué es la renuncia en seguros?', '["Voluntary giving up of a known right", "A coverage addition", "A premium increase", "A claim denial"]', '["Renuncia voluntaria de un derecho conocido", "Una adición de cobertura", "Un aumento de prima", "Una denegación de reclamo"]', 0, 'Waiver is the voluntary relinquishment of a known right by the insurer, which cannot later be enforced.', 'La renuncia es la renuncia voluntaria de un derecho conocido por el asegurador, que luego no puede hacerse cumplir.', true, '2026-01-14 22:46:59.846272', '2026-01-14 22:46:59.846272') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('a35149fa-fcf4-4fc6-bd0b-a07c76b0c39c', 'property_casualty', NULL, 'Texas follows what type of negligence rule?', '¿Texas sigue qué tipo de regla de negligencia?', '["Modified comparative negligence (51% bar rule)", "Pure comparative negligence", "Contributory negligence", "No-fault"]', '["Negligencia comparativa modificada (regla de barrera del 51%)", "Negligencia comparativa pura", "Negligencia contributiva", "Sin culpa"]', 0, 'Texas uses modified comparative negligence: a plaintiff cannot recover if they are 51% or more at fault.', 'Texas usa negligencia comparativa modificada: un demandante no puede recuperar si tiene 51% o más de culpa.', true, '2026-01-14 22:43:34.684679', '2026-01-14 22:43:34.684679') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('a3b26f17-ff19-45e7-ab36-0168a4488c2c', 'property_casualty', NULL, 'What is uninsured motorist coverage?', '¿Qué es la cobertura de motorista sin seguro?', '["Coverage for injuries caused by a driver without insurance", "Collision coverage", "Comprehensive coverage", "Liability coverage"]', '["Cobertura para lesiones causadas por un conductor sin seguro", "Cobertura de colisión", "Cobertura comprensiva", "Cobertura de responsabilidad"]', 0, 'Uninsured motorist coverage pays for injuries to you and your passengers if caused by a driver who has no insurance.', 'La cobertura de motorista sin seguro paga por lesiones a ti y tus pasajeros si son causadas por un conductor que no tiene seguro.', true, '2026-01-14 18:28:35.593677', '2026-01-14 18:28:35.593677') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('a4699565-53bb-4a30-8181-2aab15f3d7f5', 'property_casualty', NULL, 'What are the four elements required to prove negligence?', '¿Cuáles son los cuatro elementos requeridos para probar negligencia?', '["Duty, breach of duty, causation, and damages", "Intent, action, result, and proof", "Negligence, harm, payment, and settlement", "Coverage, claim, proof, and payment"]', '["Deber, incumplimiento del deber, causalidad y daños", "Intención, acción, resultado y prueba", "Negligencia, daño, pago y liquidación", "Cobertura, reclamo, prueba y pago"]', 0, 'To prove negligence, one must establish duty owed, breach of that duty, causation, and resulting damages.', 'Para probar negligencia, uno debe establecer deber debido, incumplimiento de ese deber, causalidad y daños resultantes.', true, '2026-01-14 22:43:34.679202', '2026-01-14 22:43:34.679202') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('a4f555e8-6cdb-4659-b7d0-637729ab8c65', 'property_casualty', NULL, 'What is the exclusive remedy doctrine in workers compensation?', '¿Qué es la doctrina de remedio exclusivo en compensación de trabajadores?', '["Workers comp is the only remedy for workplace injuries; employees cannot sue employers", "Employees can sue for any injury", "Multiple remedies are available", "No remedy exists"]', '["La compensación de trabajadores es el único remedio para lesiones en el trabajo; los empleados no pueden demandar a los empleadores", "Los empleados pueden demandar por cualquier lesión", "Múltiples remedios están disponibles", "No existe remedio"]', 0, 'The exclusive remedy doctrine means workers compensation is the sole remedy for workplace injuries, barring lawsuits against employers.', 'La doctrina de remedio exclusivo significa que la compensación de trabajadores es el único remedio para lesiones en el trabajo, impidiendo demandas contra empleadores.', true, '2026-01-14 22:49:00.509353', '2026-01-14 22:49:00.509353') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('a6540dfe-61a0-483f-a08e-6e34e913c9c6', 'property_casualty', NULL, 'What is the National Flood Insurance Program (NFIP)?', '¿Qué es el Programa Nacional de Seguro contra Inundaciones (NFIP)?', '["A federal program providing flood insurance to participating communities", "A private insurance company", "A state program", "A homeowners policy"]', '["Un programa federal que proporciona seguro contra inundaciones a comunidades participantes", "Una compañía de seguros privada", "Un programa estatal", "Una póliza de propietario"]', 0, 'NFIP is a federal program that provides flood insurance to property owners in participating communities.', 'NFIP es un programa federal que proporciona seguro contra inundaciones a propietarios en comunidades participantes.', true, '2026-01-14 18:28:35.629896', '2026-01-14 18:28:35.629896') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('a6b7d7aa-428a-453b-893b-08f67410b7c4', 'property_casualty', NULL, 'What is a physical hazard?', '¿Qué es un peligro físico?', '["A tangible condition that increases the likelihood or severity of a loss", "A character defect", "A type of coverage", "An insurance company"]', '["Una condición tangible que aumenta la probabilidad o severidad de una pérdida", "Un defecto de carácter", "Un tipo de cobertura", "Una compañía de seguros"]', 0, 'A physical hazard is a tangible condition (like faulty wiring) that increases the chance or magnitude of a loss.', 'Un peligro físico es una condición tangible (como cableado defectuoso) que aumenta la probabilidad o magnitud de una pérdida.', true, '2026-01-14 22:43:34.580302', '2026-01-14 22:43:34.580302') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('a9373877-460e-4083-82a1-1445e721a4ef', 'property_casualty', NULL, 'What is equipment breakdown coverage?', '¿Qué es la cobertura de avería de equipo?', '["Coverage for sudden breakdown of mechanical and electrical equipment", "Standard property coverage", "Liability coverage", "Auto coverage"]', '["Cobertura para avería súbita de equipo mecánico y eléctrico", "Cobertura estándar de propiedad", "Cobertura de responsabilidad", "Cobertura de auto"]', 0, 'Equipment breakdown coverage (boiler and machinery) covers sudden breakdown of mechanical and electrical equipment.', 'La cobertura de avería de equipo (calderas y maquinaria) cubre avería súbita de equipo mecánico y eléctrico.', true, '2026-01-14 22:46:59.71891', '2026-01-14 22:46:59.71891') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('aa0a3a2c-a5af-4f9a-8695-d153c86dc740', 'property_casualty', NULL, 'What does ''concurrent causation'' mean?', '¿Qué significa ''causalidad concurrente''?', '["When multiple causes contribute to a loss, some covered and some excluded", "A single cause of loss", "No cause of loss", "Only excluded causes"]', '["Cuando múltiples causas contribuyen a una pérdida, algunas cubiertas y algunas excluidas", "Una sola causa de pérdida", "Sin causa de pérdida", "Solo causas excluidas"]', 0, 'Concurrent causation occurs when two or more causes contribute to a loss, creating coverage disputes.', 'La causalidad concurrente ocurre cuando dos o más causas contribuyen a una pérdida, creando disputas de cobertura.', true, '2026-01-14 22:46:59.835912', '2026-01-14 22:46:59.835912') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('ab1e2561-ca96-4603-a7aa-67cf0cf1385f', 'property_casualty', NULL, 'What is the other insurance condition?', '¿Qué es la condición de otro seguro?', '["How the policy coordinates coverage when other insurance exists", "Requirement for additional insurance", "Coverage exclusion", "Premium discount"]', '["Cómo la póliza coordina cobertura cuando existe otro seguro", "Requisito de seguro adicional", "Exclusión de cobertura", "Descuento de prima"]', 0, 'The other insurance condition explains how coverage is coordinated when multiple policies cover the same loss.', 'La condición de otro seguro explica cómo se coordina la cobertura cuando múltiples pólizas cubren la misma pérdida.', true, '2026-01-14 22:46:59.700685', '2026-01-14 22:46:59.700685') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('ac477013-8e50-451f-adc2-047a224f41c7', 'property_casualty', NULL, 'What is the purpose of a premium?', '¿Cuál es el propósito de una prima?', '["The payment made by the insured in exchange for insurance coverage", "The deductible", "The claim payment", "The policy limit"]', '["El pago hecho por el asegurado a cambio de cobertura de seguro", "El deducible", "El pago del reclamo", "El límite de póliza"]', 0, 'A premium is the amount paid to the insurance company for insurance coverage.', 'Una prima es la cantidad pagada a la compañía de seguros por cobertura de seguro.', true, '2026-01-14 22:49:00.528291', '2026-01-14 22:49:00.528291') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('ad775ab9-c63d-4684-8c8f-e295ccf50648', 'property_casualty', NULL, 'What is a per-occurrence limit?', '¿Qué es un límite por ocurrencia?', '["The maximum amount paid for a single claim or occurrence", "The aggregate limit", "The deductible", "The premium"]', '["La cantidad máxima pagada por un solo reclamo u ocurrencia", "El límite agregado", "El deducible", "La prima"]', 0, 'The per-occurrence limit is the maximum the insurer will pay for any single event or claim.', 'El límite por ocurrencia es lo máximo que el asegurador pagará por cualquier evento o reclamo individual.', true, '2026-01-14 22:49:00.444907', '2026-01-14 22:49:00.444907') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('af48a4b1-19c1-481c-8ef2-b1aaf795fde5', 'property_casualty', NULL, 'What is a garage keeper''s legal liability policy?', '¿Qué es una póliza de responsabilidad legal de cuidador de garaje?', '["Coverage for damage to customers'' vehicles in the insured''s care", "Auto liability coverage", "Property coverage", "Workers compensation"]', '["Cobertura por daño a vehículos de clientes en el cuidado del asegurado", "Cobertura de responsabilidad de auto", "Cobertura de propiedad", "Compensación de trabajadores"]', 0, 'Garagekeepers coverage protects auto service businesses for damage to customers'' vehicles in their care.', 'La cobertura de cuidador de garaje protege a negocios de servicio de autos por daño a vehículos de clientes en su cuidado.', true, '2026-01-14 22:46:59.755671', '2026-01-14 22:46:59.755671') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('afe8260b-d277-4ec8-a887-e54b64147c50', 'property_casualty', NULL, 'What is coinsurance in property insurance?', '¿Qué es el coaseguro en seguros de propiedad?', '["A clause requiring the insured to carry a minimum percentage of property value", "Sharing a policy with another person", "Having two insurance companies", "A type of deductible"]', '["Una cláusula que requiere que el asegurado lleve un porcentaje mínimo del valor de la propiedad", "Compartir una póliza con otra persona", "Tener dos compañías de seguros", "Un tipo de deducible"]', 0, 'Coinsurance requires the insured to maintain coverage at a specified percentage (usually 80%) of the property''s value to receive full claim payment.', 'El coaseguro requiere que el asegurado mantenga cobertura a un porcentaje especificado (usualmente 80%) del valor de la propiedad para recibir el pago completo del reclamo.', true, '2026-01-14 22:43:34.439749', '2026-01-14 22:43:34.439749') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('b1bac7b4-75a7-4a41-aed8-906a0932aaa3', 'property_casualty', NULL, 'What is a workers compensation premium audit?', '¿Qué es una auditoría de prima de compensación de trabajadores?', '["A review to verify actual payroll compared to estimated payroll for premium calculation", "A coverage audit", "A claims audit", "A policy review"]', '["Una revisión para verificar la nómina real comparada con la nómina estimada para el cálculo de la prima", "Una auditoría de cobertura", "Una auditoría de reclamos", "Una revisión de póliza"]', 0, 'A premium audit compares actual payroll to estimated payroll to determine if additional premium is owed.', 'Una auditoría de prima compara la nómina real con la nómina estimada para determinar si se debe prima adicional.', true, '2026-01-14 22:49:00.501353', '2026-01-14 22:49:00.501353') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('b5cfd76a-d3e1-4a1a-be1e-fc629862515c', 'property_casualty', NULL, 'What is a personal auto policy (PAP)?', '¿Qué es una póliza de automóvil personal (PAP)?', '["A standard personal automobile insurance policy", "A commercial auto policy", "A motorcycle policy", "A fleet policy"]', '["Una póliza estándar de seguro de automóvil personal", "Una póliza de auto comercial", "Una póliza de motocicleta", "Una póliza de flota"]', 0, 'The PAP is the standard personal automobile insurance policy covering personal vehicles for non-commercial use.', 'La PAP es la póliza estándar de seguro de automóvil personal que cubre vehículos personales para uso no comercial.', true, '2026-01-14 22:43:34.514051', '2026-01-14 22:43:34.514051') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('b5fc448b-c2ed-41be-954f-57269a134cb5', 'property_casualty', NULL, 'What is the loss payee clause?', '¿Qué es la cláusula de beneficiario de pérdida?', '["Names a party with a financial interest to receive claim payments", "The insured only", "The agent", "The adjuster"]', '["Nombra a una parte con interés financiero para recibir pagos de reclamos", "Solo el asegurado", "El agente", "El ajustador"]', 0, 'A loss payee clause names another party (like a lienholder) to receive insurance claim payments.', 'Una cláusula de beneficiario de pérdida nombra a otra parte (como un acreedor) para recibir pagos de reclamos de seguro.', true, '2026-01-14 22:46:59.692483', '2026-01-14 22:46:59.692483') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('b7998afc-fdb0-4a12-827a-54737cbd6056', 'property_casualty', NULL, 'What is insurable interest?', '¿Qué es el interés asegurable?', '["A financial stake in the subject of insurance that would cause financial loss if destroyed", "Interest earned on premiums", "The insurance company''s profit", "A type of policy"]', '["Una participación financiera en el sujeto del seguro que causaría pérdida financiera si se destruyera", "Interés ganado sobre primas", "La ganancia de la compañía de seguros", "Un tipo de póliza"]', 0, 'Insurable interest means the insured must have a financial stake in the subject matter and would suffer financially from its loss.', 'El interés asegurable significa que el asegurado debe tener una participación financiera en el tema y sufriría financieramente por su pérdida.', true, '2026-01-14 22:43:34.567944', '2026-01-14 22:43:34.567944') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('baa94f8d-9936-452f-b505-8826dfa1f86a', 'property_casualty', NULL, 'What is an occurrence-based policy?', '¿Qué es una póliza basada en ocurrencia?', '["A policy that covers claims for incidents that occur during the policy period, regardless of when the claim is filed", "A claims-made policy", "A named peril policy", "A temporary policy"]', '["Una póliza que cubre reclamos por incidentes que ocurren durante el período de la póliza, independientemente de cuándo se presente el reclamo", "Una póliza de reclamos hechos", "Una póliza de riesgo nombrado", "Una póliza temporal"]', 0, 'An occurrence-based policy covers claims for events that happen during the policy period, even if the claim is filed years later.', 'Una póliza basada en ocurrencia cubre reclamos por eventos que suceden durante el período de la póliza, incluso si el reclamo se presenta años después.', true, '2026-01-14 22:43:34.647875', '2026-01-14 22:43:34.647875') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('bad0c0f6-33b3-4c72-ac05-3c62a13fd0aa', 'property_casualty', NULL, 'What is livestock insurance?', '¿Qué es el seguro de ganado?', '["Coverage for farm animals against death or injury from covered causes", "Property insurance", "Auto insurance", "Liability insurance"]', '["Cobertura para animales de granja contra muerte o lesión por causas cubiertas", "Seguro de propiedad", "Seguro de auto", "Seguro de responsabilidad"]', 0, 'Livestock insurance covers farm animals against death, theft, or accidental injury.', 'El seguro de ganado cubre animales de granja contra muerte, robo o lesión accidental.', true, '2026-01-14 22:46:59.791885', '2026-01-14 22:46:59.791885') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('bfb93e93-6862-43a9-a240-64e27a679c12', 'property_casualty', NULL, 'How often must a Texas P&C insurance license be renewed?', '¿Con qué frecuencia debe renovarse una licencia de seguros P&C de Texas?', '["Every 2 years", "Every year", "Every 3 years", "Every 5 years"]', '["Cada 2 años", "Cada año", "Cada 3 años", "Cada 5 años"]', 0, 'Texas insurance licenses must be renewed every two years.', 'Las licencias de seguros de Texas deben renovarse cada dos años.', true, '2026-01-14 22:43:34.390023', '2026-01-14 22:43:34.390023') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('c178f929-4b28-4c7f-8bf7-abb0007d21da', 'property_casualty', NULL, 'What is Employment Practices Liability Insurance (EPLI)?', '¿Qué es el Seguro de Responsabilidad de Prácticas Laborales (EPLI)?', '["Coverage for claims arising from employment-related issues like discrimination and wrongful termination", "Workers compensation", "Property coverage", "Auto coverage"]', '["Cobertura para reclamos que surgen de problemas relacionados con el empleo como discriminación y despido injustificado", "Compensación de trabajadores", "Cobertura de propiedad", "Cobertura de auto"]', 0, 'EPLI covers claims from employees alleging discrimination, harassment, wrongful termination, and other employment issues.', 'EPLI cubre reclamos de empleados que alegan discriminación, acoso, despido injustificado y otros problemas laborales.', true, '2026-01-14 22:46:59.732944', '2026-01-14 22:46:59.732944') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('c1d3320b-2067-4b4a-b753-bb2245a49400', 'property_casualty', NULL, 'What does a homeowners insurance policy typically cover?', '¿Qué cubre típicamente una póliza de seguro de propietarios?', '["Dwelling, personal property, liability, and additional living expenses", "Only the structure", "Only personal belongings", "Only liability"]', '["Vivienda, propiedad personal, responsabilidad y gastos de vida adicionales", "Solo la estructura", "Solo pertenencias personales", "Solo responsabilidad"]', 0, 'Standard homeowners policies cover the dwelling, other structures, personal property, liability, and additional living expenses.', 'Las pólizas estándar de propietarios cubren la vivienda, otras estructuras, propiedad personal, responsabilidad y gastos de vida adicionales.', true, '2026-01-14 22:43:34.42056', '2026-01-14 22:43:34.42056') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('c24e3b83-cf5a-4872-8f96-bcbb0c87a339', 'property_casualty', NULL, 'What is crime insurance?', '¿Qué es el seguro de crimen?', '["Coverage for losses from criminal acts like employee theft, robbery, and forgery", "Property coverage only", "Liability coverage", "Auto coverage"]', '["Cobertura por pérdidas de actos criminales como robo por empleados, atraco y falsificación", "Solo cobertura de propiedad", "Cobertura de responsabilidad", "Cobertura de auto"]', 0, 'Crime insurance covers losses from criminal acts including employee dishonesty, robbery, forgery, and computer fraud.', 'El seguro de crimen cubre pérdidas de actos criminales incluyendo deshonestidad de empleados, atraco, falsificación y fraude informático.', true, '2026-01-14 22:46:59.739141', '2026-01-14 22:46:59.739141') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('c43a367d-5c0a-4d23-b59a-5a868c8adf4a', 'property_casualty', NULL, 'What is employers liability coverage in a workers compensation policy?', '¿Qué es la cobertura de responsabilidad del empleador en una póliza de compensación de trabajadores?', '["Coverage for lawsuits by employees that are not covered under workers compensation", "Standard workers comp", "Property coverage", "Auto coverage"]', '["Cobertura para demandas de empleados que no están cubiertas bajo compensación de trabajadores", "Compensación de trabajadores estándar", "Cobertura de propiedad", "Cobertura de auto"]', 0, 'Employers liability (Part B) covers lawsuits from employees for workplace injuries not covered by workers compensation.', 'La responsabilidad del empleador (Parte B) cubre demandas de empleados por lesiones en el trabajo no cubiertas por compensación de trabajadores.', true, '2026-01-14 22:49:00.514915', '2026-01-14 22:49:00.514915') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('c4ec66b6-ae7b-4869-8cea-9a7ace470954', 'property_casualty', NULL, 'What is contractual liability coverage?', '¿Qué es la cobertura de responsabilidad contractual?', '["Coverage for liability assumed under a contract", "Property coverage", "Auto coverage", "Life coverage"]', '["Cobertura por responsabilidad asumida bajo un contrato", "Cobertura de propiedad", "Cobertura de auto", "Cobertura de vida"]', 0, 'Contractual liability coverage protects the insured for liability they''ve assumed under contracts or agreements.', 'La cobertura de responsabilidad contractual protege al asegurado por responsabilidad que han asumido bajo contratos o acuerdos.', true, '2026-01-14 22:49:00.464551', '2026-01-14 22:49:00.464551') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('c70f7a9c-2b5f-4d2b-8150-4923869d62fb', 'property_casualty', NULL, 'What is the pollution exclusion?', '¿Qué es la exclusión de contaminación?', '["An exclusion eliminating coverage for pollution-related claims", "A coverage for pollution", "A premium discount", "A claim procedure"]', '["Una exclusión que elimina cobertura para reclamos relacionados con contaminación", "Una cobertura para contaminación", "Un descuento de prima", "Un procedimiento de reclamo"]', 0, 'The pollution exclusion removes coverage for claims arising from the discharge of pollutants.', 'La exclusión de contaminación elimina cobertura para reclamos que surgen de la descarga de contaminantes.', true, '2026-01-14 22:49:00.469764', '2026-01-14 22:49:00.469764') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('c8f1cb46-0df4-4c6d-8f64-54dcc79ce2ee', 'property_casualty', NULL, 'What is a binder in insurance?', '¿Qué es un binder en seguros?', '["Temporary evidence of coverage until a formal policy is issued", "A policy cancellation", "A claim denial", "A premium refund"]', '["Evidencia temporal de cobertura hasta que se emita una póliza formal", "Una cancelación de póliza", "Una denegación de reclamo", "Un reembolso de prima"]', 0, 'A binder is temporary proof of insurance that provides coverage until the formal policy is issued.', 'Un binder es prueba temporal de seguro que proporciona cobertura hasta que se emita la póliza formal.', true, '2026-01-14 22:43:34.605164', '2026-01-14 22:43:34.605164') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('cb0225a3-b445-4576-839c-6946f4c92463', 'property_casualty', NULL, 'An insurance agent who represents multiple insurance companies is called a:', 'Un agente de seguros que representa a múltiples compañías de seguros se llama:', '["Independent agent", "Captive agent", "Exclusive agent", "Company agent"]', '["Agente independiente", "Agente cautivo", "Agente exclusivo", "Agente de compañía"]', 0, 'An independent agent represents multiple insurance companies and can offer products from various insurers.', 'Un agente independiente representa a múltiples compañías de seguros y puede ofrecer productos de varios aseguradores.', true, '2026-01-14 22:43:34.399836', '2026-01-14 22:43:34.399836') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('cbcc2ddb-9ea3-4421-a67a-68844b89abed', 'property_casualty', NULL, 'What is the difference between primary and excess coverage?', '¿Cuál es la diferencia entre cobertura primaria y excedente?', '["Primary pays first; excess pays after primary limits are exhausted", "They pay equally", "Excess pays first", "Primary never pays"]', '["Primaria paga primero; excedente paga después de que los límites primarios se agotan", "Pagan igualmente", "Excedente paga primero", "Primaria nunca paga"]', 0, 'Primary insurance pays first up to its limits, then excess coverage kicks in for amounts above those limits.', 'El seguro primario paga primero hasta sus límites, luego la cobertura excedente entra para montos por encima de esos límites.', true, '2026-01-14 22:49:00.413071', '2026-01-14 22:49:00.413071') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('cbdc2b6b-8838-42a8-87e9-80d463111659', 'property_casualty', NULL, 'What is the entire contract provision?', '¿Qué es la disposición de contrato completo?', '["The policy and attached documents constitute the complete agreement between parties", "Part of the agreement", "The premium only", "The application only"]', '["La póliza y documentos adjuntos constituyen el acuerdo completo entre las partes", "Parte del acuerdo", "Solo la prima", "Solo la solicitud"]', 0, 'The entire contract provision states that the policy and any attached documents represent the complete agreement.', 'La disposición de contrato completo establece que la póliza y cualquier documento adjunto representan el acuerdo completo.', true, '2026-01-14 22:46:59.823441', '2026-01-14 22:46:59.823441') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('ccd6fd0b-2756-47be-b314-17839ce20753', 'property_casualty', NULL, 'What is the insuring agreement?', '¿Qué es el acuerdo de seguro?', '["The section of a policy that states what the insurer promises to do", "The application", "The premium payment", "The claims process"]', '["La sección de una póliza que establece lo que el asegurador promete hacer", "La solicitud", "El pago de la prima", "El proceso de reclamos"]', 0, 'The insuring agreement is the heart of the policy, stating the insurer''s promise to pay for covered losses.', 'El acuerdo de seguro es el corazón de la póliza, estableciendo la promesa del asegurador de pagar por pérdidas cubiertas.', true, '2026-01-14 22:43:34.600347', '2026-01-14 22:43:34.600347') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('cdb2dae1-602f-46fe-b3c4-fbe4ff4349ec', 'property_casualty', NULL, 'What are the minimum liability limits required for auto insurance in Texas?', '¿Cuáles son los límites mínimos de responsabilidad requeridos para el seguro de auto en Texas?', '["30/60/25 (30K bodily injury per person, 60K per accident, 25K property damage)", "15/30/10", "50/100/50", "100/300/100"]', '["30/60/25 (30K lesiones corporales por persona, 60K por accidente, 25K daños a la propiedad)", "15/30/10", "50/100/50", "100/300/100"]', 0, 'Texas requires minimum liability coverage of 30/60/25: $30,000 bodily injury per person, $60,000 per accident, and $25,000 property damage.', 'Texas requiere cobertura mínima de responsabilidad de 30/60/25: $30,000 lesiones corporales por persona, $60,000 por accidente y $25,000 daños a la propiedad.', true, '2026-01-14 22:43:34.490553', '2026-01-14 22:43:34.490553') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('d0fb214e-080d-4928-b515-39decf09c995', 'property_casualty', NULL, 'What is reinsurance?', '¿Qué es el reaseguro?', '["Insurance purchased by insurers to transfer some of their risk", "A type of homeowners policy", "Additional coverage for consumers", "A form of self-insurance"]', '["Seguro comprado por aseguradores para transferir parte de su riesgo", "Un tipo de póliza de propietarios", "Cobertura adicional para consumidores", "Una forma de autoaseguro"]', 0, 'Reinsurance is insurance that insurers purchase to protect themselves from large or catastrophic losses.', 'El reaseguro es seguro que los aseguradores compran para protegerse de pérdidas grandes o catastróficas.', true, '2026-01-14 22:43:34.637475', '2026-01-14 22:43:34.637475') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('d1465eb2-8897-4150-b8f0-72c1a3c53207', 'property_casualty', NULL, 'What is vicarious liability?', '¿Qué es la responsabilidad vicaria?', '["Liability of one party for the acts of another (like employer for employee)", "Personal liability only", "No liability", "Product liability"]', '["Responsabilidad de una parte por los actos de otra (como empleador por empleado)", "Solo responsabilidad personal", "Sin responsabilidad", "Responsabilidad de producto"]', 0, 'Vicarious liability holds one party responsible for the negligent acts of another, such as an employer for an employee''s actions.', 'La responsabilidad vicaria hace a una parte responsable por los actos negligentes de otra, como un empleador por las acciones de un empleado.', true, '2026-01-14 22:46:59.624261', '2026-01-14 22:46:59.624261') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('d1dc5d48-5c9f-47c0-bdd3-cbaf48a12d65', 'property_casualty', NULL, 'What is the expected or intended injury exclusion?', '¿Qué es la exclusión de lesión esperada o intencional?', '["Exclusion for injuries the insured expected or intended to cause", "Coverage for intentional acts", "A premium calculation", "A claim form"]', '["Exclusión por lesiones que el asegurado esperaba o tenía la intención de causar", "Cobertura para actos intencionales", "Un cálculo de prima", "Un formulario de reclamo"]', 0, 'This exclusion removes coverage when the insured expected or intended to cause the injury or damage.', 'Esta exclusión elimina cobertura cuando el asegurado esperaba o tenía la intención de causar la lesión o el daño.', true, '2026-01-14 22:49:00.477981', '2026-01-14 22:49:00.477981') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('d447335a-558b-4ffd-acaf-cc8f6f877e2a', 'property_casualty', NULL, 'What is a declarations page?', '¿Qué es una página de declaraciones?', '["A summary page showing policy information, coverages, and premiums", "A claim form", "A cancellation notice", "An endorsement"]', '["Una página resumen que muestra información de la póliza, coberturas y primas", "Un formulario de reclamo", "Un aviso de cancelación", "Un endoso"]', 0, 'The declarations page summarizes the key elements of an insurance policy including named insured, coverage limits, deductibles, and premiums.', 'La página de declaraciones resume los elementos clave de una póliza de seguro incluyendo asegurado nombrado, límites de cobertura, deducibles y primas.', true, '2026-01-14 18:28:35.600653', '2026-01-14 18:28:35.600653') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('d511093d-de80-4f63-b47b-26087b9101d8', 'property_casualty', NULL, 'What is water damage in standard homeowners policies?', '¿Qué es el daño por agua en pólizas estándar de propietarios?', '["Sudden/accidental discharge from plumbing is covered; flood and groundwater are excluded", "All water damage is covered", "All water damage is excluded", "Only flood is covered"]', '["Descarga súbita/accidental de plomería está cubierta; inundación y agua subterránea están excluidas", "Todo daño por agua está cubierto", "Todo daño por agua está excluido", "Solo inundación está cubierta"]', 0, 'Homeowners policies cover sudden water damage from plumbing but exclude flood and groundwater damage.', 'Las pólizas de propietarios cubren daño súbito por agua de plomería pero excluyen daño por inundación y agua subterránea.', true, '2026-01-14 22:46:59.710989', '2026-01-14 22:46:59.710989') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('d58c04e9-442d-4c8a-b613-5aa746dbd48f', 'property_casualty', NULL, 'What is coinsurance in property insurance?', '¿Qué es el coaseguro en seguro de propiedad?', '["A requirement to insure property to a minimum percentage of its value", "Sharing insurance with another person", "A type of deductible", "A coverage limit"]', '["Un requisito de asegurar la propiedad a un porcentaje mínimo de su valor", "Compartir seguro con otra persona", "Un tipo de deducible", "Un límite de cobertura"]', 0, 'Coinsurance requires the policyholder to carry insurance equal to a specified percentage of the property''s value or face a penalty at claim time.', 'El coaseguro requiere que el asegurado tenga seguro igual a un porcentaje especificado del valor de la propiedad o enfrentar una penalidad al momento del reclamo.', true, '2026-01-14 18:28:35.577442', '2026-01-14 18:28:35.577442') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('d65650d1-b711-4c94-a85c-29511a99e72f', 'property_casualty', NULL, 'What is negligence in liability claims?', '¿Qué es la negligencia en reclamos de responsabilidad?', '["Failure to exercise the degree of care that a reasonable person would exercise", "Intentional harm", "An accident", "A policy exclusion"]', '["Falta de ejercer el grado de cuidado que una persona razonable ejercería", "Daño intencional", "Un accidente", "Una exclusión de póliza"]', 0, 'Negligence is the failure to use reasonable care, resulting in damage or injury to another person or property.', 'La negligencia es la falta de usar cuidado razonable, resultando en daño o lesión a otra persona o propiedad.', true, '2026-01-14 22:43:34.676291', '2026-01-14 22:43:34.676291') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('d70bb951-268b-414e-8e5f-22e810aec0e3', 'property_casualty', NULL, 'What is a surplus lines insurer?', '¿Qué es un asegurador de líneas excedentes?', '["An insurer not licensed in the state that provides coverage for hard-to-place risks", "A standard market insurer", "A government insurer", "A reinsurer"]', '["Un asegurador no licenciado en el estado que proporciona cobertura para riesgos difíciles de colocar", "Un asegurador de mercado estándar", "Un asegurador del gobierno", "Un reasegurador"]', 0, 'Surplus lines insurers are not licensed in the state but can write coverage for risks that standard insurers won''t cover.', 'Los aseguradores de líneas excedentes no están licenciados en el estado pero pueden suscribir cobertura para riesgos que los aseguradores estándar no cubrirán.', true, '2026-01-14 22:43:34.656311', '2026-01-14 22:43:34.656311') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('d82ec964-eb63-4b60-85b4-6e84876e594a', 'property_casualty', NULL, 'What is a claims-made policy?', '¿Qué es una póliza de reclamos hechos?', '["A policy that covers claims only if both the incident and the claim occur during the policy period", "An occurrence policy", "A perpetual policy", "A temporary policy"]', '["Una póliza que cubre reclamos solo si tanto el incidente como el reclamo ocurren durante el período de la póliza", "Una póliza de ocurrencia", "Una póliza perpetua", "Una póliza temporal"]', 0, 'A claims-made policy only covers claims if the incident occurred and the claim is made while the policy is in force.', 'Una póliza de reclamos hechos solo cubre reclamos si el incidente ocurrió y el reclamo se hace mientras la póliza está en vigor.', true, '2026-01-14 22:43:34.651895', '2026-01-14 22:43:34.651895') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('da6f3c44-fcf3-4840-a832-e6f762477a36', 'property_casualty', NULL, 'What is liquor liability insurance?', '¿Qué es el seguro de responsabilidad por licor?', '["Coverage for claims arising from serving alcohol", "Property coverage", "Auto coverage", "Health coverage"]', '["Cobertura para reclamos que surgen de servir alcohol", "Cobertura de propiedad", "Cobertura de auto", "Cobertura de salud"]', 0, 'Liquor liability insurance covers claims arising from the sale or service of alcohol.', 'El seguro de responsabilidad por licor cubre reclamos que surgen de la venta o servicio de alcohol.', true, '2026-01-14 22:46:59.79787', '2026-01-14 22:46:59.79787') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('db5fbca7-ec83-471a-8f84-03cd578f275b', 'property_casualty', NULL, 'What is the duty to mitigate damages?', '¿Cuál es el deber de mitigar daños?', '["The insured''s obligation to take reasonable steps to prevent further damage after a loss", "The insurer''s duty to pay claims", "A coverage limit", "A policy exclusion"]', '["La obligación del asegurado de tomar medidas razonables para prevenir más daños después de una pérdida", "El deber del asegurador de pagar reclamos", "Un límite de cobertura", "Una exclusión de póliza"]', 0, 'The duty to mitigate requires the insured to take reasonable actions to prevent further damage after a covered loss occurs.', 'El deber de mitigar requiere que el asegurado tome acciones razonables para prevenir más daños después de que ocurra una pérdida cubierta.', true, '2026-01-14 22:43:34.616935', '2026-01-14 22:43:34.616935') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('dc7c0c2e-6aa0-43c0-9843-2df01d7fe50d', 'property_casualty', NULL, 'What is an anti-concurrent causation clause?', '¿Qué es una cláusula de anti-causalidad concurrente?', '["Provision excluding coverage when an excluded peril contributes to a loss", "A coverage addition", "A premium discount", "A claim procedure"]', '["Disposición que excluye cobertura cuando un peligro excluido contribuye a una pérdida", "Una adición de cobertura", "Un descuento de prima", "Un procedimiento de reclamo"]', 0, 'An anti-concurrent causation clause excludes coverage when an excluded peril is a contributing cause of loss.', 'Una cláusula de anti-causalidad concurrente excluye cobertura cuando un peligro excluido es una causa contribuyente de pérdida.', true, '2026-01-14 22:46:59.840372', '2026-01-14 22:46:59.840372') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('def7c764-4b55-4403-8f72-3ea4ebe32a84', 'property_casualty', NULL, 'What is business interruption insurance?', '¿Qué es el seguro de interrupción de negocios?', '["Coverage for lost income when a business cannot operate due to a covered loss", "Property insurance", "Liability insurance", "Auto insurance"]', '["Cobertura por ingresos perdidos cuando un negocio no puede operar debido a una pérdida cubierta", "Seguro de propiedad", "Seguro de responsabilidad", "Seguro de auto"]', 0, 'Business interruption insurance covers lost income and ongoing expenses when a business must close due to a covered property loss.', 'El seguro de interrupción de negocios cubre ingresos perdidos y gastos continuos cuando un negocio debe cerrar debido a una pérdida de propiedad cubierta.', true, '2026-01-14 22:43:34.557805', '2026-01-14 22:43:34.557805') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('e00f19ef-aed3-4506-a7a6-e2dae7691525', 'property_casualty', NULL, 'What is replacement cost coverage?', '¿Qué es la cobertura de costo de reemplazo?', '["Coverage that pays to replace damaged property without deducting depreciation", "The cheapest coverage option", "Coverage for old items only", "Coverage minus deductible only"]', '["Cobertura que paga para reemplazar propiedad dañada sin deducir depreciación", "La opción de cobertura más barata", "Cobertura solo para artículos viejos", "Cobertura menos deducible solamente"]', 0, 'Replacement cost coverage pays the full cost to replace damaged property with new items of similar kind and quality, without depreciation.', 'La cobertura de costo de reemplazo paga el costo total para reemplazar propiedad dañada con artículos nuevos de tipo y calidad similar, sin depreciación.', true, '2026-01-14 22:43:34.431423', '2026-01-14 22:43:34.431423') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('e0671398-fdd9-4ffd-98f5-8c8c117ebb2c', 'property_casualty', NULL, 'What does Coverage B in a homeowners policy cover?', '¿Qué cubre la Cobertura B en una póliza de propietarios?', '["Other structures on the property (detached garage, fence, shed)", "The main house", "Personal belongings", "Liability claims"]', '["Otras estructuras en la propiedad (garaje separado, cerca, cobertizo)", "La casa principal", "Pertenencias personales", "Reclamos de responsabilidad"]', 0, 'Coverage B covers other structures on the property that are not attached to the dwelling, such as a detached garage or fence.', 'La Cobertura B cubre otras estructuras en la propiedad que no están adjuntas a la vivienda, como un garaje separado o cerca.', true, '2026-01-14 22:43:34.450312', '2026-01-14 22:43:34.450312') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('e19b23b5-5281-4e2c-86cc-52baccd23dd7', 'property_casualty', NULL, 'What is an insurance producer?', '¿Qué es un productor de seguros?', '["A licensed individual who sells, solicits, or negotiates insurance", "An insurance company", "A claims adjuster", "An underwriter"]', '["Un individuo licenciado que vende, solicita o negocia seguros", "Una compañía de seguros", "Un ajustador de reclamos", "Un suscriptor"]', 0, 'An insurance producer is a licensed individual who sells, solicits, or negotiates insurance contracts.', 'Un productor de seguros es un individuo licenciado que vende, solicita o negocia contratos de seguros.', true, '2026-01-14 22:43:34.403594', '2026-01-14 22:43:34.403594') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('e26d78d5-29ca-4e84-9286-7a46ecd37a59', 'property_casualty', NULL, 'What is an endorsement in insurance?', '¿Qué es un endoso en seguros?', '["A written amendment that modifies the original policy", "A premium payment", "A claim form", "A cancellation notice"]', '["Una enmienda escrita que modifica la póliza original", "Un pago de prima", "Un formulario de reclamo", "Un aviso de cancelación"]', 0, 'An endorsement (also called a rider) is a document that changes the terms, coverage, or conditions of an insurance policy.', 'Un endoso (también llamado anexo) es un documento que cambia los términos, cobertura o condiciones de una póliza de seguro.', true, '2026-01-14 18:28:35.604595', '2026-01-14 18:28:35.604595') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('e48374d5-ee23-4850-ad7e-4fc8b41c15ed', 'property_casualty', NULL, 'What is a third-party claim?', '¿Qué es un reclamo de terceros?', '["A claim made by someone who is not the insured against the insured''s policy", "A claim by the insured", "A policy endorsement", "A coverage addition"]', '["Un reclamo hecho por alguien que no es el asegurado contra la póliza del asegurado", "Un reclamo del asegurado", "Un endoso de póliza", "Una adición de cobertura"]', 0, 'A third-party claim is made by someone outside the insurance contract who seeks compensation from the insured''s liability coverage.', 'Un reclamo de terceros es hecho por alguien fuera del contrato de seguro que busca compensación de la cobertura de responsabilidad del asegurado.', true, '2026-01-14 22:43:34.627014', '2026-01-14 22:43:34.627014') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('e752e67d-e9e9-4e06-b17a-38f27b1112f0', 'property_casualty', NULL, 'What factors affect homeowners insurance premiums?', '¿Qué factores afectan las primas de seguro de propietarios?', '["Location, construction type, coverage amount, deductible, claims history, and credit score", "Only location", "Only coverage amount", "Only claims history"]', '["Ubicación, tipo de construcción, monto de cobertura, deducible, historial de reclamos y puntaje de crédito", "Solo ubicación", "Solo monto de cobertura", "Solo historial de reclamos"]', 0, 'Multiple factors affect homeowners premiums including location, construction, coverage, deductible, claims history, and credit.', 'Múltiples factores afectan las primas de propietarios incluyendo ubicación, construcción, cobertura, deducible, historial de reclamos y crédito.', true, '2026-01-14 22:49:00.531023', '2026-01-14 22:49:00.531023') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('e7fd1eef-f451-4cb3-9a5a-122e270bd214', 'property_casualty', NULL, 'What is earth movement typically classified as in property policies?', '¿Cómo se clasifica típicamente el movimiento de tierra en pólizas de propiedad?', '["An excluded peril requiring separate coverage", "A covered peril", "A standard coverage", "Included in all policies"]', '["Un peligro excluido que requiere cobertura separada", "Un peligro cubierto", "Una cobertura estándar", "Incluido en todas las pólizas"]', 0, 'Earth movement (earthquakes, landslides) is typically excluded from standard property policies and requires separate coverage.', 'El movimiento de tierra (terremotos, deslizamientos) típicamente se excluye de las pólizas estándar de propiedad y requiere cobertura separada.', true, '2026-01-14 22:46:59.707754', '2026-01-14 22:46:59.707754') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('e862c42c-7697-42b3-9323-503707239ada', 'property_casualty', NULL, 'What is the mortgagee clause?', '¿Qué es la cláusula del acreedor hipotecario?', '["Protects the mortgage lender''s interest in insured property", "Protects the insured only", "A coverage exclusion", "A premium calculation"]', '["Protege el interés del prestamista hipotecario en la propiedad asegurada", "Protege solo al asegurado", "Una exclusión de cobertura", "Un cálculo de prima"]', 0, 'The mortgagee clause protects the lender''s financial interest and ensures they receive notification of policy changes.', 'La cláusula del acreedor hipotecario protege el interés financiero del prestamista y asegura que reciban notificación de cambios en la póliza.', true, '2026-01-14 22:46:59.686999', '2026-01-14 22:46:59.686999') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('e8b94267-fdf1-4cdf-bbc3-f13686ba7875', 'property_casualty', NULL, 'What is an HO-4 policy?', '¿Qué es una póliza HO-4?', '["Renter''s insurance policy", "Homeowner''s policy", "Condo policy", "Mobile home policy"]', '["Póliza de seguro de inquilinos", "Póliza de propietarios", "Póliza de condominio", "Póliza de casa móvil"]', 0, 'HO-4 is renters insurance, covering personal property and liability for tenants who don''t own the dwelling.', 'HO-4 es seguro de inquilinos, cubriendo propiedad personal y responsabilidad para inquilinos que no son dueños de la vivienda.', true, '2026-01-14 22:43:34.483043', '2026-01-14 22:43:34.483043') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('e94f1cab-5485-4430-b2d2-6400f2dec6ae', 'property_casualty', NULL, 'What is the Texas FAIR Plan?', '¿Qué es el Plan FAIR de Texas?', '["A program providing basic property insurance for high-risk properties", "A health insurance program", "A life insurance plan", "A retirement plan"]', '["Un programa que proporciona seguro básico de propiedad para propiedades de alto riesgo", "Un programa de seguro de salud", "Un plan de seguro de vida", "Un plan de jubilación"]', 0, 'The Texas FAIR Plan Association provides basic property insurance to property owners who cannot obtain coverage in the voluntary market.', 'La Asociación del Plan FAIR de Texas proporciona seguro básico de propiedad a propietarios que no pueden obtener cobertura en el mercado voluntario.', true, '2026-01-14 18:28:35.622839', '2026-01-14 18:28:35.622839') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('e9afc7ff-6322-4d71-8ca7-c0388c7e250c', 'property_casualty', NULL, 'What is actual cash value (ACV)?', '¿Qué es el valor real en efectivo (ACV)?', '["Replacement cost minus depreciation", "Original purchase price", "Market value only", "Appraised value"]', '["Costo de reemplazo menos depreciación", "Precio de compra original", "Solo valor de mercado", "Valor tasado"]', 0, 'Actual cash value is the replacement cost of property minus depreciation for age and condition.', 'El valor real en efectivo es el costo de reemplazo de la propiedad menos la depreciación por edad y condición.', true, '2026-01-14 22:43:34.427434', '2026-01-14 22:43:34.427434') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('e9d9f6d8-f102-41b6-8b4e-840f302a23fc', 'property_casualty', NULL, 'What is a deductible?', '¿Qué es un deducible?', '["The amount the insured must pay before insurance coverage kicks in", "The premium amount", "The coverage limit", "The policy fee"]', '["La cantidad que el asegurado debe pagar antes de que la cobertura de seguro comience", "El monto de la prima", "El límite de cobertura", "La tarifa de la póliza"]', 0, 'A deductible is the out-of-pocket amount the policyholder pays before the insurance company pays a claim.', 'Un deducible es la cantidad de bolsillo que el asegurado paga antes de que la compañía de seguros pague un reclamo.', true, '2026-01-14 22:43:34.43555', '2026-01-14 22:43:34.43555') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('ea337e1b-7b66-4d7d-85d1-1db7f1783d0a', 'property_casualty', NULL, 'What is an exclusion in an insurance policy?', '¿Qué es una exclusión en una póliza de seguro?', '["A specific condition or circumstance that is not covered by the policy", "An additional coverage", "A premium reduction", "A claim payment"]', '["Una condición o circunstancia específica que no está cubierta por la póliza", "Una cobertura adicional", "Una reducción de prima", "Un pago de reclamo"]', 0, 'An exclusion is a provision that eliminates coverage for certain risks, perils, or circumstances.', 'Una exclusión es una disposición que elimina la cobertura para ciertos riesgos, peligros o circunstancias.', true, '2026-01-14 22:43:34.589469', '2026-01-14 22:43:34.589469') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('ea5b398f-56bd-4fb7-bc4b-f5af262dd9e4', 'property_casualty', NULL, 'What is a dwelling policy?', '¿Qué es una póliza de vivienda?', '["A policy for rental properties or homes that don''t qualify for standard homeowners coverage", "The same as HO-3", "A commercial policy", "A liability-only policy"]', '["Una póliza para propiedades de alquiler o casas que no califican para cobertura estándar de propietarios", "Lo mismo que HO-3", "Una póliza comercial", "Una póliza solo de responsabilidad"]', 0, 'Dwelling policies provide coverage for properties that don''t qualify for homeowners policies, such as rental properties or vacant homes.', 'Las pólizas de vivienda proporcionan cobertura para propiedades que no califican para pólizas de propietarios, como propiedades de alquiler o casas vacías.', true, '2026-01-14 22:43:34.479138', '2026-01-14 22:43:34.479138') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('ea7df247-8575-441e-8025-41cd9476089d', 'property_casualty', NULL, 'What does PIP coverage provide in auto insurance?', '¿Qué proporciona la cobertura PIP en seguro de auto?', '["Payment for medical expenses and lost wages regardless of fault", "Collision coverage", "Comprehensive coverage", "Liability coverage"]', '["Pago de gastos médicos y salarios perdidos independientemente de la culpa", "Cobertura de colisión", "Cobertura comprensiva", "Cobertura de responsabilidad"]', 0, 'Personal Injury Protection (PIP) covers medical expenses and, in many cases, lost wages, regardless of who caused the accident.', 'La Protección de Lesiones Personales (PIP) cubre gastos médicos y, en muchos casos, salarios perdidos, independientemente de quién causó el accidente.', true, '2026-01-14 18:28:35.589907', '2026-01-14 18:28:35.589907') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('ece33b0c-459f-4dc5-9dd0-46e57b2eb7f3', 'property_casualty', NULL, 'What is underwriting?', '¿Qué es la suscripción?', '["The process of evaluating and selecting risks to insure", "Selling policies", "Paying claims", "Investing premiums"]', '["El proceso de evaluar y seleccionar riesgos para asegurar", "Vender pólizas", "Pagar reclamos", "Invertir primas"]', 0, 'Underwriting is the process of evaluating risks and determining whether to accept them and at what premium.', 'La suscripción es el proceso de evaluar riesgos y determinar si aceptarlos y a qué prima.', true, '2026-01-14 22:43:34.634938', '2026-01-14 22:43:34.634938') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('eef4c690-d806-451d-bba3-1b50d0b8636c', 'property_casualty', NULL, 'What is the insuring agreement?', '¿Qué es el acuerdo de seguro?', '["The section stating what the insurer promises to cover", "The premium amount", "The deductible", "The exclusions"]', '["La sección que establece lo que el asegurador promete cubrir", "El monto de la prima", "El deducible", "Las exclusiones"]', 0, 'The insuring agreement is the policy section that describes the scope of coverage and what the insurance company agrees to do.', 'El acuerdo de seguro es la sección de la póliza que describe el alcance de la cobertura y lo que la compañía de seguros acuerda hacer.', true, '2026-01-14 18:28:35.607745', '2026-01-14 18:28:35.607745') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('f3252818-b2ed-4b13-9368-16fca921b5c0', 'property_casualty', NULL, 'What is salvage in insurance?', '¿Qué es el salvamento en seguros?', '["The value recovered from damaged property after a claim is paid", "A type of coverage", "A policy fee", "A premium"]', '["El valor recuperado de propiedad dañada después de que se paga un reclamo", "Un tipo de cobertura", "Una tarifa de póliza", "Una prima"]', 0, 'Salvage is the remaining value of damaged property that the insurer can recover after paying a total loss claim.', 'El salvamento es el valor restante de propiedad dañada que el asegurador puede recuperar después de pagar un reclamo de pérdida total.', true, '2026-01-14 22:43:34.622226', '2026-01-14 22:43:34.622226') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('f36353fa-b4c5-4323-96e2-c4d345422a03', 'property_casualty', NULL, 'What is insurable interest?', '¿Qué es el interés asegurable?', '["A financial stake in the subject of insurance that could result in loss", "Interest on premiums", "A type of coverage", "A policy endorsement"]', '["Una participación financiera en el objeto del seguro que podría resultar en pérdida", "Interés sobre primas", "Un tipo de cobertura", "Un endoso de póliza"]', 0, 'Insurable interest exists when you would suffer a financial loss if the insured property is damaged or destroyed.', 'El interés asegurable existe cuando sufrirías una pérdida financiera si la propiedad asegurada es dañada o destruida.', true, '2026-01-14 18:28:35.619367', '2026-01-14 18:28:35.619367') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('f4252dc7-e8c3-4c60-80ac-7fa83df6b6de', 'property_casualty', NULL, 'What is the purpose of a deductible in an insurance policy?', '¿Cuál es el propósito de un deducible en una póliza de seguro?', '["To increase the premium cost", "To reduce the insurance company''s exposure and the policyholder''s premium", "To eliminate all coverage", "To add more coverage"]', '["Aumentar el costo de la prima", "Reducir la exposición de la compañía de seguros y la prima del asegurado", "Eliminar toda la cobertura", "Agregar más cobertura"]', 1, 'A deductible is the amount the policyholder pays out of pocket before insurance kicks in. Higher deductibles typically mean lower premiums.', 'Un deducible es la cantidad que el asegurado paga de su bolsillo antes de que el seguro entre en vigor. Los deducibles más altos generalmente significan primas más bajas.', true, '2026-01-14 16:50:01.896369', '2026-01-14 16:50:01.896369') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('f67392c7-7ab1-4205-b8e7-711c1d73f082', 'property_casualty', NULL, 'What is an HO-6 policy?', '¿Qué es una póliza HO-6?', '["Condominium unit owners policy", "Single family homeowners policy", "Renter''s policy", "Mobile home policy"]', '["Póliza de propietarios de unidades de condominio", "Póliza de propietarios de casa unifamiliar", "Póliza de inquilinos", "Póliza de casa móvil"]', 0, 'HO-6 is designed for condominium unit owners, covering personal property, liability, and improvements to the unit.', 'HO-6 está diseñada para propietarios de unidades de condominio, cubriendo propiedad personal, responsabilidad y mejoras a la unidad.', true, '2026-01-14 22:43:34.485521', '2026-01-14 22:43:34.485521') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('f6fd044e-0e8f-47b5-99e5-20c7e902bda7', 'property_casualty', NULL, 'What is utmost good faith in insurance?', '¿Qué es la máxima buena fe en seguros?', '["Both parties must deal honestly and disclose all material information", "The insurer decides everything", "No disclosure is required", "Only the insurer must be honest"]', '["Ambas partes deben tratar honestamente y divulgar toda la información material", "El asegurador decide todo", "No se requiere divulgación", "Solo el asegurador debe ser honesto"]', 0, 'Utmost good faith (uberrimae fidei) requires both parties to deal honestly and disclose all material facts.', 'La máxima buena fe (uberrimae fidei) requiere que ambas partes traten honestamente y divulguen todos los hechos materiales.', true, '2026-01-14 22:43:34.570559', '2026-01-14 22:43:34.570559') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('f73bf3e8-6825-4c04-b900-3153a96feb2d', 'property_casualty', NULL, 'What is inland marine insurance?', '¿Qué es el seguro marino interior?', '["Coverage for property in transit or movable property not covered by standard policies", "Coverage for boats only", "Ocean cargo insurance", "Flood insurance"]', '["Cobertura para propiedad en tránsito o propiedad móvil no cubierta por pólizas estándar", "Cobertura solo para botes", "Seguro de carga oceánica", "Seguro contra inundaciones"]', 0, 'Inland marine insurance covers property in transit, movable equipment, and specialized items not adequately covered by standard property policies.', 'El seguro marino interior cubre propiedad en tránsito, equipo móvil y artículos especializados no cubiertos adecuadamente por pólizas de propiedad estándar.', true, '2026-01-14 22:43:34.559854', '2026-01-14 22:43:34.559854') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('f9278240-d96c-451e-be38-ae5f7f519845', 'property_casualty', NULL, 'What does a homeowner''s HO-3 policy cover?', '¿Qué cubre una póliza de propietario HO-3?', '["Open perils for dwelling, named perils for personal property", "Only fire damage", "Only liability", "Flood damage"]', '["Riesgos abiertos para la vivienda, riesgos nombrados para propiedad personal", "Solo daño por fuego", "Solo responsabilidad", "Daño por inundación"]', 0, 'The HO-3 is the most common homeowner''s policy, covering the dwelling on an open-perils basis and personal property on a named-perils basis.', 'El HO-3 es la póliza de propietario más común, cubriendo la vivienda en base a riesgos abiertos y propiedad personal en base a riesgos nombrados.', true, '2026-01-14 18:28:35.574415', '2026-01-14 18:28:35.574415') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('f93a5fd5-fb5a-4bed-90a8-704f19532dc7', 'property_casualty', NULL, 'What is a surety bond?', '¿Qué es una fianza?', '["A three-party agreement guaranteeing one party will fulfill obligations to another", "An insurance policy", "A bank account", "A loan"]', '["Un acuerdo de tres partes que garantiza que una parte cumplirá obligaciones con otra", "Una póliza de seguro", "Una cuenta bancaria", "Un préstamo"]', 0, 'A surety bond is a three-party contract where the surety guarantees the principal will fulfill obligations to the obligee.', 'Una fianza es un contrato de tres partes donde el fiador garantiza que el principal cumplirá obligaciones con el acreedor.', true, '2026-01-14 22:43:34.562636', '2026-01-14 22:43:34.562636') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('f9596b52-de20-4ebc-a8ac-0ad7396f7311', 'property_casualty', NULL, 'What is professional malpractice insurance?', '¿Qué es el seguro de mala práctica profesional?', '["Coverage for professionals against claims of negligent services or advice", "Property coverage", "Auto coverage", "Life coverage"]', '["Cobertura para profesionales contra reclamos de servicios o consejos negligentes", "Cobertura de propiedad", "Cobertura de auto", "Cobertura de vida"]', 0, 'Professional malpractice insurance covers claims alleging professional negligence, errors, or omissions.', 'El seguro de mala práctica profesional cubre reclamos que alegan negligencia profesional, errores u omisiones.', true, '2026-01-14 22:46:59.800858', '2026-01-14 22:46:59.800858') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('fb4f582a-4d66-4e44-b458-0c1c0dd08c1e', 'property_casualty', NULL, 'What is the purpose of policy exclusions?', '¿Cuál es el propósito de las exclusiones de la póliza?', '["To specify what is not covered by the policy", "To increase coverage", "To reduce premiums", "To add endorsements"]', '["Especificar lo que no está cubierto por la póliza", "Aumentar la cobertura", "Reducir primas", "Agregar endosos"]', 0, 'Exclusions define specific risks, circumstances, or property that the insurance policy does not cover.', 'Las exclusiones definen riesgos específicos, circunstancias o propiedades que la póliza de seguro no cubre.', true, '2026-01-14 18:28:35.612423', '2026-01-14 18:28:35.612423') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('fd9abe01-f4dc-4903-9bbe-d2c4fa4374b0', 'property_casualty', NULL, 'What is comprehensive coverage?', '¿Qué es la cobertura comprensiva?', '["Coverage for non-collision damage like theft, vandalism, weather, and animal strikes", "Coverage for collisions only", "Liability coverage", "Medical payments coverage"]', '["Cobertura por daños sin colisión como robo, vandalismo, clima e impactos de animales", "Cobertura solo por colisiones", "Cobertura de responsabilidad", "Cobertura de pagos médicos"]', 0, 'Comprehensive coverage pays for damage to your vehicle from non-collision events such as theft, vandalism, hail, fire, and animal strikes.', 'La cobertura comprensiva paga por daños a su vehículo de eventos sin colisión como robo, vandalismo, granizo, incendio e impactos de animales.', true, '2026-01-14 22:43:34.500977', '2026-01-14 22:43:34.500977') ON CONFLICT (id) DO NOTHING;
